import os
from typing import Optional

from anthropic import Anthropic


def summarize_long_text(text: str, max_output_tokens: int = 400) -> str:
    """
    Summarize long text using Anthropic's hosted Messages API.
    Requires ANTHROPIC_API_KEY in the environment.
    """
    client = Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY"))

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=max_output_tokens,
        temperature=0.2,
        messages=[
            {
                "role": "user",
                "content": (
                    "Summarize the following text clearly and concisely. "
                    "Preserve key facts, main points, and any important numbers or names.\n\n"
                    f"{text}"
                ),
            }
        ],
    )

    parts = []
    for block in response.content:
        if getattr(block, "type", None) == "text":
            parts.append(block.text)
    return "".join(parts).strip() if parts else ""


def summarize_long_text_file(path: str, max_output_tokens: int = 400) -> str:
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    return summarize_long_text(text, max_output_tokens=max_output_tokens)
